  "cons.icps.rm2d": "one positive in the whole period, in one ICP — a column that is 0 in seven of eight rows sorts by its tiebreak, not by itself.",
  "cons.icps.rm3": "Rate bars rescaled to the table leader",
  "cons.icps.rm3d": "0.4% and 9.5% are 24× apart and the old bars made them look adjacent.",
  "cons.chan.rm1": "The separate LinkedIn Connections card",
  "cons.chan.rm1d": "it rendered the same sent/accepted pair as the comparison bar with different arithmetic, so the screen showed one concept three ways and none of them was acceptance. Acceptance now has exactly one card and one number.",
  "cons.chan.rm2": "Calls inside the ranking",
  "cons.chan.rm2d": "the call card stays — connect rate, outcome mix and all — but it is out of the head-to-head, because a connect rate and a reply rate are not the same measurement.",
  "cons.chan.rm3": "The best-vs-worst gap sentence",
  "cons.chan.rm3d": "it subtracted an acceptance rate from a reply rate and printed the difference in points.",
