  "rel.example": "Example:",
  // Dispatcher failure playbook (/admin/reliability). Operator help text: cause + recommended action per failure mode.
  "rel.pb.noLi.cause": "The lead row doesn't carry primary_linkedin_url — either it was never imported, or (for client-source leads) the dispatcher couldn't decrypt it. The latter was a bug that's now fixed.",
  "rel.pb.noLi.action": "Retry. If they fail again, the lead truly has no LinkedIn URL — enrich the row or remove from the campaign.",
  "rel.pb.locked.cause": "Unipile returned 422 because the lead's LinkedIn profile is private, restricted by LinkedIn, or has been deleted. The seller is fine — the issue is the recipient. Retrying will keep failing until the lead's profile becomes reachable again (which may never happen).",
  "rel.pb.locked.action": "Don't retry. Cancel the campaign row for this lead and either remove them from the funnel or move to another channel (email / call) if you have those details. Mark the lead as archived so future imports don't re-add them.",
  "rel.pb.rateLimit.title": "LinkedIn rate-limited the seller",
  "rel.pb.rateLimit.cause": "Unipile returned a rate-limit error — the seller's LinkedIn account hit the daily invite cap or LinkedIn flagged the velocity.",
  "rel.pb.rateLimit.action": "Wait for the 4h cooldown to expire (rows auto-move to Cooldown bucket). Reduce daily limit on the seller if this keeps happening.",
  "rel.pb.dupInvite.cause": "LinkedIn blocks re-invites within ~3 weeks of a previous attempt. Often happens when a lead was re-uploaded under a different campaign.",
  "rel.pb.dupInvite.action": "Wait 3 weeks for LinkedIn's block to clear, then retry. Alternatively, move to email channel.",
  "rel.pb.restricted.title": "Seller's LinkedIn account is restricted",
  "rel.pb.restricted.cause": "The seller's Unipile account is in restricted state — typically from too many invites flagged as spam.",
  "rel.pb.restricted.action": "Pause the seller. Have them warm up the account manually (login, engage 1-2 days), then resume.",
  "rel.pb.noUnipile.cause": "The seller's user record lacks unipile_account_id — they're either not onboarded yet or their connection was deauth'd.",
  "rel.pb.noUnipile.action": "Reconnect the seller's LinkedIn in /admin/<tenant>/Sellers.",
  "rel.pb.deleted.cause": "Someone deleted the lead row (or the parent campaign) between when the message was queued and when the dispatcher ran.",
  "rel.pb.deleted.action": "These messages are zombies — safe to ignore. We should add a cron to garbage-collect them.",
  "rel.errors": "Errors",
  "rel.nPositive": "{n} positive",
  "rel.groupedBy": "Grouped by cause · click a row to expand",
