  "rel.example": "Ejemplo:",
  // Dispatcher failure playbook (/admin/reliability). Operator help text: cause + recommended action per failure mode.
  "rel.pb.noLi.cause": "La fila del lead no trae primary_linkedin_url — o nunca se importó, o (en leads de origen cliente) el dispatcher no pudo desencriptarla. Eso último era un bug ya arreglado.",
  "rel.pb.noLi.action": "Reintentá. Si vuelven a fallar, el lead realmente no tiene URL de LinkedIn — enriquecé la fila o sacalo de la campaña.",
  "rel.pb.locked.cause": "Unipile devolvió 422 porque el perfil de LinkedIn del lead es privado, está restringido por LinkedIn o fue borrado. El vendedor está bien — el problema es el destinatario. Reintentar va a seguir fallando hasta que el perfil vuelva a ser alcanzable (que puede no pasar nunca).",
  "rel.pb.locked.action": "No reintentes. Cancelá la fila de campaña de este lead y sacalo del funnel o pasalo a otro canal (email / llamada) si tenés esos datos. Marcá el lead como archivado para que futuras importaciones no lo vuelvan a agregar.",
  "rel.pb.rateLimit.title": "LinkedIn limitó al vendedor por volumen",
  "rel.pb.rateLimit.cause": "Unipile devolvió un error de rate limit — la cuenta de LinkedIn del vendedor llegó al tope diario de invitaciones o LinkedIn marcó la velocidad.",
  "rel.pb.rateLimit.action": "Esperá que expire el cooldown de 4h (las filas se mueven solas al bucket de Cooldown). Bajá el límite diario del vendedor si sigue pasando.",
  "rel.pb.dupInvite.cause": "LinkedIn bloquea las re-invitaciones dentro de ~3 semanas de un intento anterior. Suele pasar cuando un lead se volvió a subir en otra campaña.",
  "rel.pb.dupInvite.action": "Esperá 3 semanas a que se libere el bloqueo de LinkedIn y reintentá. O pasalo al canal de email.",
  "rel.pb.restricted.title": "La cuenta de LinkedIn del vendedor está restringida",
  "rel.pb.restricted.cause": "La cuenta de Unipile del vendedor está en estado restringido — normalmente por demasiadas invitaciones marcadas como spam.",
  "rel.pb.restricted.action": "Pausá al vendedor. Que caliente la cuenta a mano (login, interactuar 1-2 días) y después retomá.",
  "rel.pb.noUnipile.cause": "El registro del vendedor no tiene unipile_account_id — o todavía no está onboardeado o su conexión se desautorizó.",
  "rel.pb.noUnipile.action": "Reconectá el LinkedIn del vendedor en /admin/<tenant>/Sellers.",
  "rel.pb.deleted.cause": "Alguien borró la fila del lead (o la campaña padre) entre que el mensaje se puso en cola y que corrió el dispatcher.",
  "rel.pb.deleted.action": "Estos mensajes son zombies — se pueden ignorar. Deberíamos agregar un cron que los limpie.",
